head.script:
scwin.onpageload = function() {
	requires("uiplugin.popup");
};
scwin.openPopup = function(accessibility) {
	var opt = {
		id: 'popupTest01',
		popupName: 'test',
		type: 'wframePopup',
		width: '500px',
		height: '300px',
		top: '140px',
		left: '500px',
		modal: true,
		alwaysOnTop: false,
		useModalStack: true,
		resizable: true,
		useMaximize: false,
		className: "",
		scrollbars: true,
		disableCloseButton: false,
		accessibility: accessibility
	};
	$p.openPopup("/sample/common_link/p_openPopup_wframePopup_accessibility_WESE-1099_(WSQ-6028)_popup.xml", opt);
};
scwin.btn_wframePopup1_onclick = function(e) {
	scwin.openPopup(true);
};
scwin.btn_wframePopup2_onclick = function(e) {
	scwin.openPopup(false);
};
scwin.checkVal = function() {
	return document.getElementById('mf_popupTest01_wframe_ipx_name').classList.contains("w2input_focus");
};
